const threads = [
  { id: 't1', owner: 'u-a', tenant: 't-1', title: 'Returns' },
  { id: 't2', owner: 'u-b', tenant: 't-1', title: 'Shipping' },
];
function listThreads(principal) {
  return threads.filter((t) => t.owner === principal.userId && t.tenant === principal.tenantId).map((t) => t.id);
}
function readThread(principal, id) {
  const t = threads.find((x) => x.id === id);
  if (!t || t.owner !== principal.userId || t.tenant !== principal.tenantId) return { error: 'forbidden' };
  return { thread: t };
}
console.log(listThreads({ userId: 'u-a', tenantId: 't-1' }).join(','));
console.log(JSON.stringify(readThread({ userId: 'u-b', tenantId: 't-1' }, 't1')));
console.log(JSON.stringify(readThread({ userId: 'u-a', tenantId: 't-1' }, 't1').thread.title));

